CREATE TABLE alembic_version (version_num varchar(32) not null primary key);
INSERT INTO "alembic_version" VALUES('f38623b35077');
CREATE TABLE annotation_presets (
	id INTEGER NOT NULL, 
	name VARCHAR NOT NULL, 
	pos VARCHAR NOT NULL, 
	gender VARCHAR, 
	number VARCHAR, 
	"case" VARCHAR, 
	declension VARCHAR, 
	article_type VARCHAR, 
	pronoun_type VARCHAR, 
	pronoun_number VARCHAR, 
	verb_class VARCHAR, 
	verb_tense VARCHAR, 
	verb_person VARCHAR, 
	verb_mood VARCHAR, 
	verb_aspect VARCHAR, 
	verb_form VARCHAR, 
	verb_direct_object_case VARCHAR, 
	verb_requires_infinitive BOOLEAN DEFAULT 0 NOT NULL, 
	verb_impersonal BOOLEAN DEFAULT 0 NOT NULL, 
	verb_transitivity VARCHAR DEFAULT 'transitive' NOT NULL, 
	adjective_inflection VARCHAR, 
	adjective_degree VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_annotation_presets_name_pos UNIQUE (name, pos), 
	CONSTRAINT ck_annotation_presets_pos CHECK (pos IN ('N','V','A','R','D')), 
	CONSTRAINT ck_annotation_presets_verb_transitivity CHECK (verb_transitivity IN ('transitive','intransitive'))
);
CREATE TABLE annotations (
	id INTEGER NOT NULL, 
	token_id INTEGER, 
	idiom_id INTEGER, 
	pos VARCHAR, 
	gender VARCHAR, 
	number VARCHAR, 
	"case" VARCHAR, 
	declension VARCHAR, 
	article_type VARCHAR, 
	pronoun_type VARCHAR, 
	pronoun_number VARCHAR, 
	verb_class VARCHAR, 
	verb_tense VARCHAR, 
	verb_person VARCHAR, 
	verb_mood VARCHAR, 
	verb_aspect VARCHAR, 
	verb_form VARCHAR, 
	verb_direct_object_case VARCHAR, 
	verb_requires_infinitive BOOLEAN DEFAULT 0 NOT NULL, 
	verb_impersonal BOOLEAN DEFAULT 0 NOT NULL, 
	verb_transitivity VARCHAR DEFAULT 'transitive' NOT NULL, 
	prep_case VARCHAR, 
	adjective_inflection VARCHAR, 
	adjective_degree VARCHAR, 
	conjunction_type VARCHAR, 
	adverb_degree VARCHAR, 
	confidence INTEGER, 
	last_inferred_json VARCHAR, 
	modern_english_meaning VARCHAR, 
	sense VARCHAR, 
	root VARCHAR, 
	root_normalized VARCHAR, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_annotations_pos CHECK (pos IN ('N','V','A','R','D','B','C','E','I', 'L')), 
	CONSTRAINT ck_annotations_gender CHECK (gender IN ('m','f','n')), 
	CONSTRAINT ck_annotations_number CHECK (number IN ('s','p')), 
	CONSTRAINT ck_annotations_case CHECK ("case" IN ('n','a','g','d','i')), 
	CONSTRAINT ck_annotations_declension CHECK (declension IN ('s','w','o','i','u','ja','jo','wa','wo','pu', 'r', 'i-mut', 'er', 'nd', 'th')), 
	CONSTRAINT ck_annotations_pronoun_type CHECK (pronoun_type IN ('p','rx','r','d','i','m','ind')), 
	CONSTRAINT ck_annotations_pronoun_number CHECK (pronoun_number IN ('s','d','pl')), 
	CONSTRAINT ck_annotations_article_type CHECK (article_type IN ('d','i','p','D')), 
	CONSTRAINT ck_annotations_verb_class CHECK (verb_class IN ('a','w1','w2','w3','pp','s1','s2','s3','s4','s5','s6','s7')), 
	CONSTRAINT ck_annotations_verb_tense CHECK (verb_tense IN ('p','n')), 
	CONSTRAINT ck_annotations_verb_person CHECK (verb_person IN ('1','2','3')), 
	CONSTRAINT ck_annotations_verb_mood CHECK (verb_mood IN ('i','s','imp')), 
	CONSTRAINT ck_annotations_verb_aspect CHECK (verb_aspect IN ('p','f','prg','gn')), 
	CONSTRAINT ck_annotations_verb_form CHECK (verb_form IN ('f','i','p','ii')), 
	CONSTRAINT ck_annotations_verb_direct_object_case CHECK (verb_direct_object_case IN ('n', 'a','d','g','i')), 
	CONSTRAINT ck_annotations_verb_transitivity CHECK (verb_transitivity IN ('transitive','intransitive')), 
	CONSTRAINT ck_annotations_prep_case CHECK (prep_case IN ('a','d','g','i')), 
	CONSTRAINT ck_annotations_confidence CHECK (confidence >= 0 AND confidence <= 100), 
	CONSTRAINT ck_annotations_adjective_inflection CHECK (adjective_inflection IN ('s','w')), 
	CONSTRAINT ck_annotations_adjective_degree CHECK (adjective_degree IN ('p','c','s')), 
	CONSTRAINT ck_annotations_conjunction_type CHECK (conjunction_type IN ('c','s')), 
	CONSTRAINT ck_annotations_adverb_degree CHECK (adverb_degree IN ('p','c','s')), 
	FOREIGN KEY(token_id) REFERENCES tokens (id) ON DELETE CASCADE, 
	FOREIGN KEY(idiom_id) REFERENCES idioms (id) ON DELETE CASCADE
);
CREATE TABLE chapters (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	number INTEGER NOT NULL, 
	title VARCHAR, 
	title_auto BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE
);
CREATE TABLE idioms (
	id INTEGER NOT NULL, 
	sentence_id INTEGER NOT NULL, 
	start_token_id INTEGER NOT NULL, 
	end_token_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sentence_id) REFERENCES sentences (id) ON DELETE CASCADE, 
	FOREIGN KEY(start_token_id) REFERENCES tokens (id) ON DELETE CASCADE, 
	FOREIGN KEY(end_token_id) REFERENCES tokens (id) ON DELETE CASCADE
);
CREATE TABLE notes (
	id INTEGER NOT NULL, 
	sentence_id INTEGER NOT NULL, 
	start_token INTEGER, 
	end_token INTEGER, 
	note_text_md VARCHAR NOT NULL, 
	note_type VARCHAR NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_notes_note_type CHECK (note_type IN ('token','span','sentence')), 
	FOREIGN KEY(sentence_id) REFERENCES sentences (id) ON DELETE CASCADE, 
	FOREIGN KEY(start_token) REFERENCES tokens (id) ON DELETE CASCADE, 
	FOREIGN KEY(end_token) REFERENCES tokens (id) ON DELETE CASCADE
);
CREATE TABLE paragraphs (
	id INTEGER NOT NULL, 
	section_id INTEGER NOT NULL, 
	"order" INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(section_id) REFERENCES sections (id) ON DELETE CASCADE
);
CREATE TABLE projects (
	id INTEGER NOT NULL, 
	name VARCHAR NOT NULL, 
	source VARCHAR, 
	translator VARCHAR, 
	notes VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE remembered_annotations (
	id INTEGER NOT NULL, 
	project_id INTEGER, 
	token_text VARCHAR NOT NULL, 
	pos VARCHAR, 
	gender VARCHAR, 
	number VARCHAR, 
	"case" VARCHAR, 
	declension VARCHAR, 
	article_type VARCHAR, 
	pronoun_type VARCHAR, 
	pronoun_number VARCHAR, 
	verb_class VARCHAR, 
	verb_tense VARCHAR, 
	verb_person VARCHAR, 
	verb_mood VARCHAR, 
	verb_aspect VARCHAR, 
	verb_form VARCHAR, 
	verb_direct_object_case VARCHAR, 
	verb_requires_infinitive BOOLEAN DEFAULT 0 NOT NULL, 
	verb_impersonal BOOLEAN DEFAULT 0 NOT NULL, 
	verb_transitivity VARCHAR DEFAULT 'transitive' NOT NULL, 
	prep_case VARCHAR, 
	adjective_inflection VARCHAR, 
	adjective_degree VARCHAR, 
	conjunction_type VARCHAR, 
	adverb_degree VARCHAR, 
	modern_english_meaning VARCHAR, 
	root VARCHAR, 
	root_normalized VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_remembered_annotations_pos CHECK (pos IN ('N','V','A','R','D','B','C','E','I', 'L')), 
	CONSTRAINT ck_remembered_annotations_gender CHECK (gender IN ('m','f','n')), 
	CONSTRAINT ck_remembered_annotations_number CHECK (number IN ('s','p')), 
	CONSTRAINT ck_remembered_annotations_case CHECK ("case" IN ('n','a','g','d','i')), 
	CONSTRAINT ck_remembered_annotations_declension CHECK (declension IN ('s','w','o','i','u','ja','jo','wa','wo','pu', 'r', 'i-mut', 'er', 'nd', 'th')), 
	CONSTRAINT ck_remembered_annotations_pronoun_type CHECK (pronoun_type IN ('p','rx','r','d','i','m','ind')), 
	CONSTRAINT ck_remembered_annotations_pronoun_number CHECK (pronoun_number IN ('s','d','pl')), 
	CONSTRAINT ck_remembered_annotations_article_type CHECK (article_type IN ('d','i','p','D')), 
	CONSTRAINT ck_remembered_annotations_verb_class CHECK (verb_class IN ('a','w1','w2','w3','pp','s1','s2','s3','s4','s5','s6','s7')), 
	CONSTRAINT ck_remembered_annotations_verb_tense CHECK (verb_tense IN ('p','n')), 
	CONSTRAINT ck_remembered_annotations_verb_person CHECK (verb_person IN ('1','2','3')), 
	CONSTRAINT ck_remembered_annotations_verb_mood CHECK (verb_mood IN ('i','s','imp')), 
	CONSTRAINT ck_remembered_annotations_verb_aspect CHECK (verb_aspect IN ('p','f','prg','gn')), 
	CONSTRAINT ck_remembered_annotations_verb_form CHECK (verb_form IN ('f','i','p','ii')), 
	CONSTRAINT ck_remembered_annotations_verb_direct_object_case CHECK (verb_direct_object_case IN ('n', 'a','d','g','i')), 
	CONSTRAINT ck_remembered_annotations_verb_transitivity CHECK (verb_transitivity IN ('transitive','intransitive')), 
	CONSTRAINT ck_remembered_annotations_prep_case CHECK (prep_case IN ('a','d','g','i')), 
	CONSTRAINT ck_remembered_annotations_adjective_inflection CHECK (adjective_inflection IN ('s','w')), 
	CONSTRAINT ck_remembered_annotations_adjective_degree CHECK (adjective_degree IN ('p','c','s')), 
	CONSTRAINT ck_remembered_annotations_conjunction_type CHECK (conjunction_type IN ('c','s')), 
	CONSTRAINT ck_remembered_annotations_adverb_degree CHECK (adverb_degree IN ('p','c','s')), 
	FOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE
);
CREATE TABLE sections (
	id INTEGER NOT NULL, 
	chapter_id INTEGER NOT NULL, 
	number INTEGER NOT NULL, 
	title VARCHAR, 
	title_auto BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chapter_id) REFERENCES chapters (id) ON DELETE CASCADE
);
CREATE TABLE sentences (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	paragraph_id INTEGER, 
	display_order INTEGER NOT NULL, 
	text_oe VARCHAR NOT NULL, 
	text_modern VARCHAR, 
	verse_line_start INTEGER, 
	verse_line_end INTEGER, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_sentences_project_order UNIQUE (project_id, display_order), 
	FOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, 
	FOREIGN KEY(paragraph_id) REFERENCES paragraphs (id) ON DELETE CASCADE
);
CREATE TABLE tokens (
	id INTEGER NOT NULL, 
	sentence_id INTEGER NOT NULL, 
	order_index INTEGER NOT NULL, 
	surface VARCHAR NOT NULL, 
	surface_normalized VARCHAR NOT NULL, 
	lemma VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_tokens_sentence_order UNIQUE (sentence_id, order_index), 
	FOREIGN KEY(sentence_id) REFERENCES sentences (id) ON DELETE CASCADE
);
CREATE INDEX idx_chapters_project_number ON chapters (project_id, number);
CREATE UNIQUE INDEX uq_remembered_annotations_project_token_text ON remembered_annotations (project_id, token_text) WHERE project_id IS NOT NULL;
CREATE INDEX idx_remembered_annotations_project_id ON remembered_annotations (project_id);
CREATE UNIQUE INDEX uq_remembered_annotations_global_token_text ON remembered_annotations (token_text) WHERE project_id IS NULL;
CREATE INDEX idx_sections_chapter_number ON sections (chapter_id, number);
CREATE INDEX idx_paragraphs_section_order ON paragraphs (section_id, "order");
CREATE INDEX idx_sentences_paragraph_order ON sentences (paragraph_id, display_order);
CREATE INDEX idx_idioms_sentence_token_span ON idioms (sentence_id, start_token_id, end_token_id);
CREATE INDEX idx_notes_sentence ON notes (sentence_id);
CREATE INDEX idx_annotations_token_id ON annotations (token_id);
CREATE INDEX idx_annotations_idiom_id ON annotations (idiom_id);
